scene.newBattle:
newBattle(waveIndex?: integer, battleType?: BattleType, trainerData?: TrainerData, double?: boolean): Battle {
		let newWaveIndex = waveIndex || ((this.currentBattle?.waveIndex || (startingWave - 1)) + 1);
		let newDouble: boolean;
		let newBattleType: BattleType;
		let newTrainer: Trainer;

		let battleConfig: FixedBattleConfig = null;

		this.resetSeed(newWaveIndex);

		const playerField = this.getPlayerField();

		if (this.gameMode.hasFixedBattles && fixedBattles.hasOwnProperty(newWaveIndex) && trainerData === undefined) {
			battleConfig = fixedBattles[newWaveIndex];
			newDouble = battleConfig.double;
			newBattleType = battleConfig.battleType;
			this.executeWithSeedOffset(() => newTrainer = battleConfig.getTrainer(this), (battleConfig.seedOffsetWaveIndex || newWaveIndex) << 8);
			if (newTrainer)
				this.field.add(newTrainer);
		} else {
			if (!this.gameMode.hasTrainers)
				newBattleType = BattleType.WILD;
			else if (battleType === undefined)
				newBattleType = this.gameMode.isWaveTrainer(newWaveIndex, this.arena) ? BattleType.TRAINER : BattleType.WILD;
			else
				newBattleType = battleType;

			if (newBattleType === BattleType.TRAINER) {
				const trainerType = this.arena.randomTrainerType(newWaveIndex);
				let doubleTrainer = false;
				if (trainerConfigs[trainerType].doubleOnly)
					doubleTrainer = true;
				else if (trainerConfigs[trainerType].hasDouble) {
					const doubleChance = new Utils.IntegerHolder(newWaveIndex % 10 === 0 ? 32 : 8);
					this.applyModifiers(DoubleBattleChanceBoosterModifier, true, doubleChance);
					playerField.forEach(p => applyAbAttrs(DoubleBattleChanceAbAttr, p, null, doubleChance));
					doubleTrainer = !Utils.randSeedInt(doubleChance.value);
				}
				newTrainer = trainerData !== undefined ? trainerData.toTrainer(this) : new Trainer(this, trainerType, doubleTrainer ? TrainerVariant.DOUBLE : Utils.randSeedInt(2) ? TrainerVariant.FEMALE : TrainerVariant.DEFAULT);
				this.field.add(newTrainer);
			}
		}

		if (double === undefined && newWaveIndex > 1) {
			if (newBattleType === BattleType.WILD && !this.gameMode.isWaveFinal(newWaveIndex)) {
				const doubleChance = new Utils.IntegerHolder(newWaveIndex % 10 === 0 ? 32 : 8);
				this.applyModifiers(DoubleBattleChanceBoosterModifier, true, doubleChance);
				playerField.forEach(p => applyAbAttrs(DoubleBattleChanceAbAttr, p, null, doubleChance));
				newDouble = !Utils.randSeedInt(doubleChance.value);
			} else if (newBattleType === BattleType.TRAINER)
				newDouble = newTrainer.variant === TrainerVariant.DOUBLE;
		} else if (!battleConfig)
			newDouble = !!double;

		const lastBattle = this.currentBattle;

		const maxExpLevel = this.getMaxExpLevel();

		this.lastEnemyTrainer = lastBattle?.trainer ?? null;

		this.currentBattle = new Battle(this.gameMode, newWaveIndex, newBattleType, newTrainer, newDouble);
		this.currentBattle.incrementTurn(this);

		//this.pushPhase(new TrainerMessageTestPhase(this, TrainerType.RIVAL, TrainerType.RIVAL_2, TrainerType.RIVAL_3, TrainerType.RIVAL_4, TrainerType.RIVAL_5, TrainerType.RIVAL_6));

		if (!waveIndex && lastBattle) {
			const isNewBiome = !(lastBattle.waveIndex % 10) || (this.gameMode.isDaily && lastBattle.waveIndex === 49);
			const resetArenaState = isNewBiome || this.currentBattle.battleType === BattleType.TRAINER || this.currentBattle.battleSpec === BattleSpec.FINAL_BOSS;
			this.getEnemyParty().forEach(enemyPokemon => enemyPokemon.destroy());
			this.trySpreadPokerus();
			if (!isNewBiome && (newWaveIndex % 10) == 5)
				this.arena.updatePoolsForTimeOfDay();
			if (resetArenaState) {
				this.arena.removeAllTags();
				playerField.forEach((_, p) => this.unshiftPhase(new ReturnPhase(this, p)));
				this.unshiftPhase(new ShowTrainerPhase(this));
			}
			for (let pokemon of this.getParty()) {
				if (pokemon) {
					if (resetArenaState)
						pokemon.resetBattleData();
					this.triggerPokemonFormChange(pokemon, SpeciesFormChangeTimeOfDayTrigger);
				}
			}
			if (!this.gameMode.hasRandomBiomes && !isNewBiome)
				this.pushPhase(new NextEncounterPhase(this));
			else {
				this.pushPhase(new SelectBiomePhase(this));
				this.pushPhase(new NewBiomeEncounterPhase(this));

				const newMaxExpLevel = this.getMaxExpLevel();
				if (newMaxExpLevel > maxExpLevel)
					this.pushPhase(new LevelCapPhase(this));
			}
		}

		return this.currentBattle;
	}

scene.resetSeed:
resetSeed(waveIndex?: integer): void {
		this.waveSeed = Utils.shiftCharCodes(this.seed, waveIndex || this.currentBattle?.waveIndex || 0);
		Utils.getSceneRandom().sow([ this.waveSeed ]);
	}

scene.trySpreadPokerus:
trySpreadPokerus(): void {
		const party = this.getParty();
		const infectedIndexes: integer[] = [];
		party.forEach((pokemon, p) => {
			if (!pokemon.pokerus || infectedIndexes.indexOf(p) > -1)
				return;

			this.executeWithSeedOffset(() => {
				if (p) {
					const partyMember = party[p - 1];
					if (!partyMember.pokerus && !Utils.randSeedInt(10)) {
						partyMember.pokerus = true;
						infectedIndexes.push(p - 1);
					}
				}

				if (p < party.length - 1) {
					const partyMember = party[p + 1];
					if (!partyMember.pokerus && !Utils.randSeedInt(10)) {
						partyMember.pokerus = true;
						infectedIndexes.push(p + 1);
					}
				}
			}, this.currentBattle.waveIndex + (p << 8));
		});
	}

scene.generateEnemyModifiers:
generateEnemyModifiers(): Promise<void> {
		return new Promise(resolve => {
			if (this.currentBattle.battleSpec === BattleSpec.FINAL_BOSS)
				return resolve();
			const difficultyWaveIndex = this.gameMode.getWaveForDifficulty(this.currentBattle.waveIndex);
			const isFinalBoss = this.gameMode.isWaveFinal(this.currentBattle.waveIndex);
			let chances = Math.ceil(difficultyWaveIndex / 10);
			if (isFinalBoss)
				chances = Math.ceil(chances * 2.5);

			const party = this.getEnemyParty();

			if (this.currentBattle.trainer) {
				const modifiers = this.currentBattle.trainer.genModifiers(party);
				for (let modifier of modifiers)
					this.addEnemyModifier(modifier, true, true);
			}

			party.forEach((enemyPokemon: EnemyPokemon, i: integer) => {
				const isBoss = enemyPokemon.isBoss() || (this.currentBattle.battleType === BattleType.TRAINER && this.currentBattle.trainer.config.isBoss);
				let upgradeChance = 32;
				if (isBoss)
					upgradeChance /= 2;
				if (isFinalBoss)
					upgradeChance /= 8;
				const modifierChance = this.gameMode.getEnemyModifierChance(isBoss);
				let pokemonModifierChance = modifierChance;
				if (this.currentBattle.battleType === BattleType.TRAINER)
					pokemonModifierChance = Math.ceil(pokemonModifierChance * this.currentBattle.trainer.getPartyMemberModifierChanceMultiplier(i));
				let count = 0;
				for (let c = 0; c < chances; c++) {
					if (!Utils.randSeedInt(modifierChance))
						count++;
				}
				if (isBoss)
					count = Math.max(count, Math.floor(chances / 2));
				getEnemyModifierTypesForWave(difficultyWaveIndex, count, [ enemyPokemon ], this.currentBattle.battleType === BattleType.TRAINER ? ModifierPoolType.TRAINER : ModifierPoolType.WILD, upgradeChance)
					.map(mt => mt.newModifier(enemyPokemon).add(this.enemyModifiers, false, this));
			});

			this.updateModifiers(false).then(() => resolve());
		});
	}

EncounterPhase.start:
start() {
    super.start();

    this.scene.initSession();

    const loadEnemyAssets = [];

    const battle = this.scene.currentBattle;

    let totalBst = 0;

    battle.enemyLevels.forEach((level, e) => {
      if (!this.loaded) {
        if (battle.battleType === BattleType.TRAINER)
          battle.enemyParty[e] = battle.trainer.genPartyMember(e);
        else {
          const enemySpecies = this.scene.randomSpecies(battle.waveIndex, level, true);
          battle.enemyParty[e] = this.scene.addEnemyPokemon(enemySpecies, level, TrainerSlot.NONE, !!this.scene.getEncounterBossSegments(battle.waveIndex, level, enemySpecies));
          if (this.scene.currentBattle.battleSpec === BattleSpec.FINAL_BOSS)
            battle.enemyParty[e].ivs = new Array(6).fill(31);
          this.scene.getParty().slice(0, !battle.double ? 1 : 2).reverse().forEach(playerPokemon => {
            applyAbAttrs(SyncEncounterNatureAbAttr, playerPokemon, null, battle.enemyParty[e]);
          });
        }
      }
      const enemyPokemon = this.scene.getEnemyParty()[e];
      if (e < (battle.double ? 2 : 1)) {
        enemyPokemon.setX(-66 + enemyPokemon.getFieldPositionOffset()[0]);
        enemyPokemon.resetSummonData();
        if (!this.loaded)
          this.scene.gameData.setPokemonSeen(enemyPokemon);
      }

      if (enemyPokemon.species.speciesId === Species.ETERNATUS) {
        if (this.scene.gameMode.isClassic && (battle.battleSpec === BattleSpec.FINAL_BOSS || this.scene.gameMode.isWaveFinal(battle.waveIndex))) {
          if (battle.battleSpec !== BattleSpec.FINAL_BOSS) {
            enemyPokemon.formIndex = 1;
            enemyPokemon.updateScale();
          }
          enemyPokemon.setBoss();
        } else if (!(battle.waveIndex % 1000)) {
          enemyPokemon.formIndex = 1;
          enemyPokemon.updateScale();
        }
      }

      totalBst += enemyPokemon.getSpeciesForm().baseTotal;

      loadEnemyAssets.push(enemyPokemon.loadAssets());

      console.log(enemyPokemon.name, enemyPokemon.species.speciesId, enemyPokemon.stats);
    });

    if (battle.battleType === BattleType.TRAINER)
      loadEnemyAssets.push(battle.trainer.loadAssets().then(() => battle.trainer.initSprite()));
    else {
      if (battle.enemyParty.filter(p => p.isBoss()).length > 1) {
        for (let enemyPokemon of battle.enemyParty) {
          if (enemyPokemon.isBoss()) {
            enemyPokemon.setBoss(true, Math.ceil(enemyPokemon.bossSegments * (enemyPokemon.getSpeciesForm().baseTotal / totalBst)));
            enemyPokemon.initBattleInfo();
          }
        }
      }
    }

    Promise.all(loadEnemyAssets).then(() => {
      battle.enemyParty.forEach((enemyPokemon, e) => {
        if (e < (battle.double ? 2 : 1)) {
          if (battle.battleType === BattleType.WILD) {
            this.scene.field.add(enemyPokemon);
            battle.seenEnemyPartyMemberIds.add(enemyPokemon.id);
            const playerPokemon = this.scene.getPlayerPokemon();
            if (playerPokemon?.visible)
              this.scene.field.moveBelow(enemyPokemon as Pokemon, playerPokemon);
            enemyPokemon.tint(0, 0.5);
          } else if (battle.battleType === BattleType.TRAINER) {
            enemyPokemon.setVisible(false);
            this.scene.currentBattle.trainer.tint(0, 0.5);
          }
          if (battle.double)
            enemyPokemon.setFieldPosition(e ? FieldPosition.RIGHT : FieldPosition.LEFT);
        }
      });

      if (!this.loaded) {
        regenerateModifierPoolThresholds(this.scene.getEnemyField(), battle.battleType === BattleType.TRAINER ? ModifierPoolType.TRAINER : ModifierPoolType.WILD);
        this.scene.generateEnemyModifiers();
      }

      this.scene.ui.setMode(Mode.MESSAGE).then(() => {
        if (!this.loaded) {
          this.scene.gameData.saveSystem().then(success => {
            if (!success)
              return this.scene.reset(true);
            this.scene.gameData.saveSession(this.scene, true).then(() => this.doEncounter());
          });
        } else
          this.doEncounter();
      });
    });
  }

EncounterPhase.doEncounterCommon:
doEncounterCommon(showEncounterMessage: boolean = true) {
    const enemyField = this.scene.getEnemyField();

    if (this.scene.currentBattle.battleType === BattleType.WILD) {
      enemyField.forEach(enemyPokemon => {
        enemyPokemon.untint(100, 'Sine.easeOut');
        enemyPokemon.cry();
        enemyPokemon.showInfo();
        if (enemyPokemon.isShiny())
          this.scene.validateAchv(achvs.SEE_SHINY);
      });
      this.scene.updateFieldScale();
      if (showEncounterMessage)
        this.scene.ui.showText(this.getEncounterMessage(), null, () => this.end(), 1500);
      else
        this.end();
    } else if (this.scene.currentBattle.battleType === BattleType.TRAINER) {
      const trainer = this.scene.currentBattle.trainer;
      trainer.untint(100, 'Sine.easeOut');
      trainer.playAnim();

      const doSummon = () => {
        this.scene.currentBattle.started = true;
        this.scene.playBgm(undefined);
        this.scene.pbTray.showPbTray(this.scene.getParty());
			  this.scene.pbTrayEnemy.showPbTray(this.scene.getEnemyParty());
        const doTrainerSummon = () => {
          this.hideEnemyTrainer();
          const availablePartyMembers = this.scene.getEnemyParty().filter(p => !p.isFainted()).length;
          this.scene.unshiftPhase(new SummonPhase(this.scene, 0, false));
          if (this.scene.currentBattle.double && availablePartyMembers > 1)
            this.scene.unshiftPhase(new SummonPhase(this.scene, 1, false));
          this.end();
        };
        if (showEncounterMessage)
          this.scene.ui.showText(this.getEncounterMessage(), null, doTrainerSummon, 1500, true);
        else
          doTrainerSummon();
      };

      const encounterMessages = this.scene.currentBattle.trainer.getEncounterMessages();

      if (!encounterMessages?.length)
        doSummon();
      else {
        const showDialogueAndSummon = () => {
          let message: string;
          this.scene.executeWithSeedOffset(() => message = Utils.randSeedItem(encounterMessages), this.scene.currentBattle.waveIndex);
          this.scene.ui.showDialogue(message, trainer.getName(), null, () => {
            this.scene.charSprite.hide().then(() => this.scene.hideFieldOverlay(250).then(() => doSummon()));
          });
        };
        if (this.scene.currentBattle.trainer.config.hasCharSprite)
          this.scene.showFieldOverlay(500).then(() => this.scene.charSprite.showCharacter(trainer.getKey(), getCharVariantFromDialogue(encounterMessages[0])).then(() => showDialogueAndSummon()));
        else
          showDialogueAndSummon();
      }
    }
  }

EncounterPhase.getEncounterMessage:
getEncounterMessage(): string {
    const enemyField = this.scene.getEnemyField();

    if (this.scene.currentBattle.battleSpec === BattleSpec.FINAL_BOSS)
      return `${enemyField[0].name} appeared.`;

    if (this.scene.currentBattle.battleType === BattleType.TRAINER)
      return `${this.scene.currentBattle.trainer.getName(TrainerSlot.NONE, true)}\nwould like to battle!`;

    return enemyField.length === 1
      ? i18next.t('battle:singleWildAppeared', { pokemonName: enemyField[0].name })
      : i18next.t('battle:multiWildAppeared', { pokemonName1: enemyField[0].name, pokemonName2: enemyField[1].name });
  }

EncounterPhase.end:
end() {
    const enemyField = this.scene.getEnemyField();

    enemyField.forEach((enemyPokemon, e) => {
      if (enemyPokemon.isShiny())
        this.scene.unshiftPhase(new ShinySparklePhase(this.scene, BattlerIndex.ENEMY + e));
    });

    if (this.scene.currentBattle.battleType !== BattleType.TRAINER) {
      enemyField.map(p => this.scene.pushPhase(new PostSummonPhase(this.scene, p.getBattlerIndex())));
      const ivScannerModifier = this.scene.findModifier(m => m instanceof IvScannerModifier);
      if (ivScannerModifier)
        enemyField.map(p => this.scene.pushPhase(new ScanIvsPhase(this.scene, p.getBattlerIndex(), Math.min(ivScannerModifier.getStackCount(), 6))));
    }

    if (!this.loaded) {
      const availablePartyMembers = this.scene.getParty().filter(p => !p.isFainted());

      if (availablePartyMembers[0].isOnField())
        applyPostBattleInitAbAttrs(PostBattleInitAbAttr, availablePartyMembers[0]);
      else
        this.scene.pushPhase(new SummonPhase(this.scene, 0));

      if (this.scene.currentBattle.double) {
        if (availablePartyMembers.length > 1) {
          this.scene.pushPhase(new ToggleDoublePositionPhase(this.scene, true));
          if (availablePartyMembers[1].isOnField())
            applyPostBattleInitAbAttrs(PostBattleInitAbAttr, availablePartyMembers[1]);
          else
            this.scene.pushPhase(new SummonPhase(this.scene, 1));
        }
      } else {
        if (availablePartyMembers.length > 1 && availablePartyMembers[1].isOnField())
          this.scene.pushPhase(new ReturnPhase(this.scene, 1));
        this.scene.pushPhase(new ToggleDoublePositionPhase(this.scene, false));
      }

      if (this.scene.currentBattle.waveIndex > startingWave && this.scene.currentBattle.battleType !== BattleType.TRAINER) {
        this.scene.pushPhase(new CheckSwitchPhase(this.scene, 0, this.scene.currentBattle.double));
        if (this.scene.currentBattle.double && availablePartyMembers.length > 1)
          this.scene.pushPhase(new CheckSwitchPhase(this.scene, 1, this.scene.currentBattle.double));
      }
    }

    handleTutorial(this.scene, Tutorial.Access_Menu).then(() => super.end());
  }

EncounterPhase.tryOverrideForBattleSpec:
tryOverrideForBattleSpec(): boolean {
    switch (this.scene.currentBattle.battleSpec) {
      case BattleSpec.FINAL_BOSS:
        const enemy = this.scene.getEnemyPokemon();
        this.scene.ui.showText(this.getEncounterMessage(), null, () => {
          this.scene.ui.showDialogue(battleSpecDialogue[BattleSpec.FINAL_BOSS].encounter, enemy.species.name, null, () => {
            this.doEncounterCommon(false);
          });
        }, 1500, true);
        return true;
    }

    return false;
  }

NextEncounterPhase.doEncounter:
doEncounter(): void {
    this.scene.playBgm(undefined, true);

    for (let pokemon of this.scene.getParty()) {
      if (pokemon)
        pokemon.resetBattleData();
    }

    this.scene.arenaNextEnemy.setVisible(true);

    const enemyField = this.scene.getEnemyField();
    this.scene.tweens.add({
      targets: [ this.scene.arenaEnemy, this.scene.arenaNextEnemy, this.scene.currentBattle.trainer, enemyField, this.scene.lastEnemyTrainer ].flat(),
      x: '+=300',
      duration: 2000,
      onComplete: () => {
        this.scene.arenaEnemy.setX(this.scene.arenaNextEnemy.x);
        this.scene.arenaEnemy.setAlpha(1);
        this.scene.arenaNextEnemy.setX(this.scene.arenaNextEnemy.x - 300);
        this.scene.arenaNextEnemy.setVisible(false);
        if (this.scene.lastEnemyTrainer)
          this.scene.lastEnemyTrainer.destroy();

        if (!this.tryOverrideForBattleSpec())
          this.doEncounterCommon();
      }
    });
  }

PostSummonPhase.start:
start() {
    super.start();

    const pokemon = this.getPokemon();

    this.scene.arena.applyTags(ArenaTrapTag, pokemon);
    applyPostSummonAbAttrs(PostSummonAbAttr, pokemon).then(() => this.end());
  }

ToggleDoublePositionPhase.start:
start() {
    super.start();

    const playerPokemon = this.scene.getPlayerField().find(p => p.isActive(true));
    if (playerPokemon) {
      playerPokemon.setFieldPosition(this.double && this.scene.getParty().filter(p => !p.isFainted()).length > 1 ? FieldPosition.LEFT : FieldPosition.CENTER, 500).then(() => {
        if (playerPokemon.getFieldIndex() === 1) {
          const party = this.scene.getParty();
          party[1] = party[0];
          party[0] = playerPokemon;
        }
        this.end();
      });
    } else
      this.end();
  }

CheckSwitchPhase.start:
start() {
    super.start();

    const pokemon = this.scene.getPlayerField()[this.fieldIndex];

    if (this.scene.field.getAll().indexOf(pokemon) === -1) {
      this.scene.unshiftPhase(new SummonMissingPhase(this.scene, this.fieldIndex));
      super.end();
      return;
    }

    if (!this.scene.getParty().slice(1).filter(p => p.isActive()).length) {
      super.end();
      return;
    }

    if (pokemon.getTag(BattlerTagType.FRENZY)) {
      super.end();
      return;
    }

    this.scene.ui.showText(i18next.t("battle:switchQuestion", { pokemonName: (this.useName ? pokemon.name : 'Pokémon') }), null, () => {
      this.scene.ui.setMode(Mode.CONFIRM, () => {
        this.scene.ui.setMode(Mode.MESSAGE);
        this.scene.unshiftPhase(new SwitchPhase(this.scene, this.fieldIndex, false, true));
        this.end();
      }, () => {
        this.scene.ui.setMode(Mode.MESSAGE);
        this.end();
      });
    });
  }

arenaRandomSpecies:
randomSpecies(waveIndex: integer, level: integer, attempt?: integer): PokemonSpecies {
    const overrideSpecies = this.scene.gameMode.getOverrideSpecies(waveIndex);
    if (overrideSpecies)
      return overrideSpecies;
    const isBoss = !!this.scene.getEncounterBossSegments(waveIndex, level) && !!this.pokemonPool[BiomePoolTier.BOSS].length
      && (this.biomeType !== Biome.END || this.scene.gameMode.isClassic || this.scene.gameMode.isWaveFinal(waveIndex));
    const tierValue = Utils.randSeedInt(!isBoss ? 512 : 64);
    let tier = !isBoss
      ? tierValue >= 156 ? BiomePoolTier.COMMON : tierValue >= 32 ? BiomePoolTier.UNCOMMON : tierValue >= 6 ? BiomePoolTier.RARE : tierValue >= 1 ? BiomePoolTier.SUPER_RARE : BiomePoolTier.ULTRA_RARE
      : tierValue >= 20 ? BiomePoolTier.BOSS : tierValue >= 6 ? BiomePoolTier.BOSS_RARE : tierValue >= 1 ? BiomePoolTier.BOSS_SUPER_RARE : BiomePoolTier.BOSS_ULTRA_RARE;
    console.log(BiomePoolTier[tier]);
    while (!this.pokemonPool[tier].length) {
      console.log(`Downgraded rarity tier from ${BiomePoolTier[tier]} to ${BiomePoolTier[tier - 1]}`);
      tier--;
    }
    const tierPool = this.pokemonPool[tier];
    let ret: PokemonSpecies;
    let regen = false;
    if (!tierPool.length)
      ret = this.scene.randomSpecies(waveIndex, level);
    else {
      const entry = tierPool[Utils.randSeedInt(tierPool.length)];
      let species: Species;
      if (typeof entry === 'number')
        species = entry as Species;
      else {
        const levelThresholds = Object.keys(entry);
        for (let l = levelThresholds.length - 1; l >= 0; l--) {
          const levelThreshold = parseInt(levelThresholds[l]);
          if (level >= levelThreshold) {
            const speciesIds = entry[levelThreshold];
            if (speciesIds.length > 1)
              species = speciesIds[Utils.randSeedInt(speciesIds.length)];
            else
              species = speciesIds[0];
            break;
          }
        }
      }

      ret = getPokemonSpecies(species);

      if (ret.pseudoLegendary || ret.legendary || ret.mythical) {
        switch (true) {
          case (ret.baseTotal >= 720):
            regen = level < 90;
            break;
          case (ret.baseTotal >= 670):
            regen = level < 70;
            break;
          case (ret.baseTotal >= 580):
            regen = level < 50;
            break;
          default:
            regen = level < 30;
            break;
        }
      }
    }

    if (regen && (attempt || 0) < 10) {
      console.log('Incompatible level: regenerating...');
      return this.randomSpecies(waveIndex, level, (attempt || 0) + 1);
    }

    const newSpeciesId = ret.getWildSpeciesForLevel(level, true, isBoss, this.scene.gameMode);
    if (newSpeciesId !== ret.speciesId) {
      console.log('Replaced', Species[ret.speciesId], 'with', Species[newSpeciesId]);
      ret = getPokemonSpecies(newSpeciesId);
    }
    return ret;
  }
